export const SEED_CH7 = `-- Chapter 7: Management and Administration of Companies
insert into public.mcq_questions (book_id, chapter_no, chapter_title, question_no, question, options, correct_index, hint)
select b.id, 7, 'Management and Administration of Companies', v.question_no, v.question, v.options, v.correct_index, v.hint
from public.books b
cross join lateral (values
(1, 'Which types of registers shall be maintained by company?', '["Register of members","Register of debenture holders","Register of other security holders","All of the above"]'::jsonb, 3, 'As per section 88(1) of the Companies Act, 2013, all the aforesaid registers shall be maintained in a manner and format as may be prescribed.'),
(2, 'Which register shall be compulsorily maintained by company?', '["Register of members","Register of debenture holders","Register of other security holders","All of the above"]'::jsonb, 0, 'Section 88 of the Companies Act, 2013'),
(3, 'Total days of one time closure of register of members or debenture holders or other security holders shall not exceed……. Days.', '["10 days","20 days","30 days","45 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013, maximum period of closure.'),
(4, 'Total closure days in year together of all closure of register of members or debenture holders or other security holders shall not exceed……. Days.', '["30 days","40 days","45 days","60 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013, maximum period of closure.'),
(5, 'Notice regarding closure of books and registers of members or debenture holders or other security holders to SEBI & ROC at least ….. Days before the first day of closure.', '["1 day","5 days","7 days","10 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013, maximum period of closure.'),
(6, 'State the penalty for every day during which the register is kept closed in contravention of Section 91 of the Companies Act, 2013, for Compan y and every officer in default…', '["Rs. 5,000 per day of default or Rs. 100000, whichever is lower","Rs. 5,000 per day of default or Rs. 100000, whichever is Higher","Rs. 10,000 per day of default or Rs. 100000, whichever is Higher","Rs. 10,000 per day of default or Rs. 100000, whichever is lower"]'::jsonb, 0, 'Section 91(2) of the Companies Act, 2013.'),
(7, 'ABC Ltd. is a public limited company desires to declare dividend. For that company will need to close registers of members or debenture holders or other security holders. In how many days company should inform about closure of registers to SEBI & ROC?', '["1 day","5 days","7 days","10 days"]'::jsonb, 2, 'Section 91(1) of the Companies Act, 2013.'),
(8, 'Can annual general meeting be held on a national holiday?', '["Yes","No","Specific Cases","After approval of shareholders"]'::jsonb, 1, 'Under section 96(2) of the Companies Act, 2013 every annual general meeting shall be called during nosiness hours i.e. between 9 a.m. to 6 p.m. on any day that is not a national holiday'),
(9, 'First Annual General meeting shall be within period of …… months from the date of closing of the first financial year of the company.', '["3 months","6 months","9 months","15 months Section 96(1) of the Companies Act, 2013, time limit to hold AGM."]'::jsonb, 2, 'Section 96(1) of the Compa nies Act, 2013, time limit to hold AGM'),
(12, 'The Financial year of ABC Ltd. ended on 31 st March, 2018, The Annual General meeting of the company was held on 10 th October, 2018. As per requirement of the Companies Act, 2013, the Annual Return of the company should be filed with Registrar of Companies within ……', '["60 days from 10 th October, 2018","60 days from 30 th September, 2018","90 days from 30 th September, 2018","90 days from 10 th October, 2018"]'::jsonb, 1, 'As per Section 92(4) of the Companies act, 2013, every Company shall file with the Registrar a copy of the Annual Return, within 60 days from the date on which the annual general meeting is held or where no annual general meeting is held in any year within 60 days from the date on which annual general meeting should have been held together with the statement specifying the reasons for not holding annual general meeting, with such fees or additional fees as may be prescribed.'),
(13, 'The gap between two Annual General Meeting must not be more than', '["12 months as may be extended by Registrar of Companies to 18 months","15 months as may be extended by Registrar of Companies to 20 months","18 months as may be extended by Registrar of Companies to 20 months","15 months as may be extended by Registrar of Companies to 18 months"]'::jsonb, 3, 'As per Section 96(1) of the Companies Act, 2013, not more than 15 months shall elapse between the date of one Annual General Meeting and that of the next. However, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(14, 'The Financial year of ABC Ltd. ended on 31 st March, 2020, due to some specific reason, the company will not be eligible to conduct the Annual General meeting of the company at or before 30 th September, 2020. Whether Company can apply to the Registrar of Companies for extension of time for the Annual General meeting?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 0, 'As per Section 96(1) of the Companies Act, 2013, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(15, 'An extra ordinary general meeting may be convened by…….', '["Board of Directors","Requistionists","Company Law Board/Tribunal","All of the above"]'::jsonb, 3, 'Section 98 & 100 of the Companie s Act, 2013.'),
(16, 'The time period for conduction of AGM is extended by ROC for how many months?', '["1 month","2 months","4 months","3 months"]'::jsonb, 3, 'As per Section 96(1) of the Companies Act, 2013, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(17, 'M/s Infotech Ltd. was incorporated on 1 st April, 2015. No general meeting of the company has been held within a period of 9 months from the date of closing of the first financial year of the company. Whether registrar can grant extension of time for the first Annual General Meeting?', '["Yes","No","Exceptional cases","None of the above"]'::jsonb, 1, 'As per Section 96(1) of the Companies Act, 2013, the Registrar may, for specific reason, extend the time within which any AGM (not being the first AGM) shall be held, by a period not exceeding 3 months.'),
(18, 'Resolution requiring special notice is required……', '["For appointment of a person other than the retiring auditor as auditor at the Annual General Meeting","For removing a director before the expiry of the period of his office","Both a and b","None of the abo ve"]'::jsonb, 2, 'Section 169(2) & 140(4) of the Companies Act, 2013.'),
(22, 'Every listed company shall file a return specifying the change in the number of shares held by promoters and top 10 shareholders and such return shall be filed with ROC within ……. Days of such change.', '["7 days","10 days","15 days","30 days"]'::jsonb, 2, 'Section 93 of the Compani es Act, 2013.'),
(23, 'The registers and indexes and copies of annual return shall be kept at……….', '["The registered office of the company","Any other place in India if more than 10% of the total number of members reside at such place","Both a and b","None of the above"]'::jsonb, 2, 'Section 94(1) of the Companies Act, 2013, any other place in India if more than 10% of the total number of members reside at such place(GM-SR required and ROC has been given in advance a copy of the proposed SR'),
(24, 'All the records(only public documents) shall be open for inspection by', '["Any member or debenture holders","other security holders or beneficial owner","Any other person","All of the above"]'::jsonb, 3, 'Section 94(2) of the Companies Act, 2013, all the records (only public documents) shall be open for inspection by Any member or debenture holders or other security holders or beneficial owner without fees and Any other person with fees.'),
(25, 'If the company refuses to allow any inspection or taking of any extract, penalty for the company and every officer in default shall be', '["Rs. 1,000 per day of defaulting period or Rs. 1,00,000 whichever is lower","Rs. 1,000 per day of defaulting period or Rs. 1,00,000 whichever is higher","Rs. 2,000 per day of defaulting period or Rs. 1,00,000 whichever is higher","Rs. 2,000 per day of defaulting period or Rs. 2,00,000 whichever is lower"]'::jsonb, 0, 'Section 94(4) of the Companie s Act, 2013'),
(26, 'Mr. Ram is a shareholder of M/s ABC Ltd. desires to inspect the registers of the company. Whether he can do so?', '["Yes","No","Approval BOD","Approval other shareholders"]'::jsonb, 0, 'Section 94(2) of the Companies Act, 2013, all the records (only public documents) shall be open for inspection by Any member or debenture holders or other security holders or beneficial owner without fees and Any other person with fees.'),
(28, 'M/s XYZ Pvt. Ltd, is a Private limited company, incorporated at 30 th September, 2018. State the date of First Annual General meeting.', '["30.09.2019","31.12.2019","30.09.2020","31.12.2020"]'::jsonb, 1, 'The First Annual General Meeting of the company shall be held within 9 months from the end of first financial year. The First Financial year of M/s XYZ Pvt. Ltd. ended on 31 st March, 2019. (Section 96(1) of the Companies Act, 2013)'),
(29, 'M/s XYZ Ltd, is a public limited company, incorporated at 1 st January, 2019. State the date of First Annual General meeting.', '["30.09.2020","31.12.2020","30.09.2021","31.12.2021"]'::jsonb, 1, 'The First Annual General Meeting of the company shall be held within 9 months from the end of first financial year. The First Financial year of M/s XYZ Ltd. ended on 31 st March, 2020. (Section 96(1) of the Companies Act, 2013)'),
(30, 'M/s ABC Pvt. Ltd, is a Private limited company, incorporated at 31 st March, 2019. State the date of First Annual General meeting.', '["30.09.2020","31.12.2020","30.09.2021","31.12.2021"]'::jsonb, 1, 'The First Annual General Meeting of the company shall be held within 9 months from the end of first financial year. The First Financial year of M/s ABC Pvt. Ltd. ended on 31 st March, 2020. (Section 96(1) of the Companies Act, 2013)'),
(31, 'If any default is made in holding the Annual General meeting under section 96 of the Companies Act, 2013, an application to call or direct calling of meeting is made to the …. By any member.', '["High Court","SEBI","NCLT","None of the above"]'::jsonb, 2, 'Section 97(1) of the Companies Act, 2013, Power of Tribunal to call or direct calling of meeting.'),
(32, 'If any default is made in holding the Annual General meeting under section 96 of the Companies Act, 2013, an application to call or direct calling of meeting is made to the Tribunal by …………..', '["Promoters","Board of directors","Any shareholders","None of the above"]'::jsonb, 2, 'Section 97(1) of the Companies Act, 2013, Power of Tribunal to call or direct calling of meeting.'),
(33, 'When for any reason it is impractical to call a meeting other than an annual general meeting of a company, an application is made by any director or member who would be entitled to vote at such meeting. The Tribunal may, sou motu be of opinion to order such meeting of members. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 0, 'Section 98(1) of the Companies Act, 2013, Power of Tribunal to call meeting of members.'),
(34, 'If any default is made in holding a meeting of a company as per Section 96, 97 or 98 of the Companies Act, 2013 or complying with any directions of the Tribunal, penalty for the company and every officer in default..', '["For one time default – Fine up to Rs. 1,00,000 For Continuing Default – Fine up to Rs. 5,000 per day for the defaulting period","For one time default – Fine up to Rs. 2,00,000 For Continuing Default – Fine up to Rs. 5,000 per day for the defaulting period","For one time default – Fine up to Rs. 1,00,000 For Continuing Default – Fine up to Rs. 1,000 per day for the defaulting period","For one time default – Fine up to Rs. 2,00,000 For Continuing Default – Fine up to Rs. 2,000 per day for the defaulting period"]'::jsonb, 0, 'Section 99 of the Companies Act, 2013, punishment for default in complying with provision of Section 96 to Section 98 of the Companies Act, 2013'),
(35, 'Who can make a valid requisition in case of company having a share capital?', '["Members holding 5% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition","Member holding 10% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition","Member holding 20% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition","Member holding 51% or more of the paid up share capital of the company having a right to vote as at the date of deposit of the requisition"]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013'),
(36, 'Who can make a valid requisition in case of company not having a share capital?', '["Members having 5% or more of the total voting power of all the members as at the date of deposit of the requisition.","Members having 10% or more of the total voting power of all the members as at the date of deposit of the requisition.","Members having 20% or more of the total voting power of all the members as at the date of deposit of the requisition.","Members having 51% or more of the total voting power of all the members as at the date of deposit of the requisition."]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013'),
(37, 'The Board of Directors shall call an Extra Ordinary general meeting on receiving valid requisition from members on a day not later than…… days from the date of receipt of such requisition.', '["30 days","45 days","60 days","90 days"]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013, Board of Directors legally bound to call Extra Ordinary general meeting on receiving valid requisition from members.'),
(38, 'The Board of Directors shall within …. Days from the date of receipt of valid requisition from members, proceed to call an Extra Ordinary general meeting.', '["15 days","21 days","45 days","30 days"]'::jsonb, 1, 'Section 100(2) of the Companies Act, 2013, Board of Directors legally bound to call Extra Ordinary general meeting on receiving valid requisition from members.'),
(39, 'If board fails to call the Extra Ordinary general meeting on receiving valid requisition from members, the meeting may be called and held by requisitonists themselves within a period of ………. Months from the date of the requisition.', '["1 Month","2 Months","3 Months","6 Months"]'::jsonb, 2, 'Section 100(4) of the Companies Act, 2013'),
(40, 'Which are the items of business that require special notice?', '["– Resolution at AGM appointing as auditor a person other than retiring auditor. - Resolution at AGM providing expressly that retiring auditor shall not be reappointed","– Resolution for removal of a director. - Resolution to appoint somebody in place of a director removed at the meeting at which he is removed","Both a and b","None of the above"]'::jsonb, 2, 'Section 115 of the companies Act, 2013, resolutions required special notice.'),
(41, 'The special notice is given by members holding not less than ……… total voting power or holding shares on which such aggregate sum not exceeding …… rupees, as may be prescribed has been paid up.', '["1%, Rs. 5 Lakh","10%, Rs. 5 Lakh","1%, Rs. 10 Lakh","10%, Rs. 10 Lakh"]'::jsonb, 0, 'Section 115 of the companies Act, 2013, resolutions required special notice.'),
(42, 'Mr. Ram is a shareholder of the M/s ABC Ltd. Company , having 2% voting power, desires to call an Extra Ordinary general meeting. Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'Removal of director is a one of the business which requires special notice. The special notice is given by members holding not less than 1% total voting power or holding shares on which such aggregate sum not exceeding 5 lakhs'),
(43, 'Mr. Shyam is a shareholder of the M/s ABC Ltd. Company , having less than 1% voting power, desires to call an Extra Ordinary general meeting for appointment as auditor a person other than retiring auditor. Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 1, 'Appointment as auditor a person other than retiring auditor is a one of the business which requires special notice. The special notice is given by members holding not less than 1% total voting power or holding shares on which such aggregate sum not exceeding 5 lakhs rupees,'),
(44, 'Mr. Shyam is a shareholder of the M/s ABC Ltd. Company , holding shares of aggregate sum is Rs. 5 lakhs, desires to call an Extra Ordinary general meeting for removal of director. Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'Removal of director is a one of the business which requires special notice. The special notice is given by members holding not less than 1% total voting power or holding shares on which such aggregate sum not exceeding 5 lakhs rupees, as may be'),
(45, 'Mr. Ram is a shareholder of the M/s ABC Ltd. ( Company not having a share capital ) , having 10% voting power, desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'As per Section 100 of the Companies Act, 2013, In case of Company not having a share capital, members having 10% voting power of all the members as at the date of deposit of the re quisition have right to make requisition.'),
(46, 'Mr. Shyam is a shareholder of the M/s ABC Ltd. ( Company having a share capital ) , holding 10% of the paid up share capital of the company having right to vote , desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 0, 'As per Section 100 of the Companies Act, 2013, In case of Company having a share capital, members holding 10% of the paid up share capital of the company having right to vote as at the date of deposit of the requisition have right to make requisition.'),
(47, 'Mr. Rajesh is a shareholder of the M/s ABC Ltd. (Company having a share capital), holding 1% of the paid up share capital of the company having right to vote, desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 1, 'As per Section 100 of the Companies Act, 2013, In case of Company having a share capital, members holding 10% of the paid up share capital of the company having right to vote as at the date of deposit of the requisition have right to make requisition'),
(48, 'Mr. Kiran is a shareholder of the M/s ABC Ltd. (Company not having a share capital), having 1% voting power, desires to requisites an Extra Ordinary general meeting for other than those business which require special notice . Whether he can do so?', '["Yes","No","With permission of NCLT","With permission of other shareholders"]'::jsonb, 1, 'As per Section 100 of the Companies Act, 2013, In case of Company not having a share capital, members having 10% voting power of all the members as at the date of deposit of the requisition have right to make requisition.'),
(51, 'The Board of Director of a company refuse to convene the Extra Ordinary general meeting of the members on the ground that the reqisitionists have not been signed by the joint holder of the shares. (Power of attorney is assumed one) Whether Board of Director can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Where 2 or more persons hold any shares or interest in a company jointly, a requisition or notice calling a meeting, signed by one or some of them shall, for the purpose of Section 100 of the Companies Act, 2013, have same force and effect as if it had been signed by all of them.'),
(52, 'M/s XYZ Ltd. called its Annual General Meeting on 28 th September, 2018. The notice of the meeting was posted on 6 th September, 2018. With reference to the provision of the Companies Act, 2013 examine whether the notice given by the company was valid?', '["Valid","Invalid","Valid after approval Board","can’t say"]'::jsonb, 1, 'As per Section 101 of the Companies Act, 2013, 21 clear days’ notice has not been served.'),
(53, 'Who are the persons entitled to receive notice of a general meeting of a company, registered under the Companies Act, 2013?', '["To every member of the company, legal representative of any deceased member, or the assignee of an insolvent member","To every director of the company","To an auditor or auditors","All of the above"]'::jsonb, 3, 'Section 101 of the Companies Act, 2013'),
(54, 'Accidental Non receipt of notice of the general meeting by any member invalidate the proceeding of the meeting?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Accidental Non receipt of notice of the general meeting by any member shall not invalidate the proceeding of the meeting(Section 101 of the Companies Act, 2013'),
(56, 'Every notice shall specify…….', '["Date and day of the meeting","Place and hour of the meeting","Business to be transacted","All of the above"]'::jsonb, 3, 'Section 101 of the Compani es Act, 2013.'),
(57, 'Any General Meeting can be called by giving at least ………. Clear days’ notice .', '["7 days","14 days","21 days","30 days"]'::jsonb, 3, 'Section 101 of the Companies Act, 2013.'),
(58, 'Mr. Rajesh, secretary of ABC Ltd. called an Extra Ordinary general meeting of the company on the requisition of some members. Mr. Rajesh, secretary of the company issued notice of the meeting without the authority of the Board of Directors. Whether he can do so?', '["Yes","No","in specific cases, it is allowed","can’t say"]'::jsonb, 2, 'Section 101 of the Companies Act, 2013.'),
(59, 'Mr. Rajesh, secretary of ABC Ltd. called an Extra Ordinary general meeting of the company on the requisition of some members. Mr. Rajesh, secretary of the company issued notice of the meeting without the authority of the Board of Directors. Mr. Rajesh, secretary of the company is already specially authorized by Board of Directors and AOA of the company for the same. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 101 and 115 of the Companies Act, 2013.'),
(60, 'Explanatory statement must be annexed to the notice for transacting every item of ………….. Business.', '["Ordinary","Special","All of the above","None of the above"]'::jsonb, 0, 'Section 101 and 115 of the Companies Act, 2013.'),
(61, 'Contents of Explanatory statement………..', '["the nature of concern or interest , financial or otherwise, in respect of each items of every director and manager and their relatives","the nature of concern or interest , financial or otherwise, in respect of each items of every other key managerial personnel and their relatives","any other information and facts that may enable members to understand the meaning, scope and implications of the items of business","All of the ab ov e"]'::jsonb, 1, 'Section 102(1) of the Companies Act, 2013'),
(62, 'All business to be transacted at Annual General Meeting shall be deemed special except……….', '["the consideration of financial statement and the reports of the Board of directors and auditors","Declaration of dividend","the appointment of director in place of those retiring and the appointment of , and the fixing of the remuneration of, the auditors","All of th e ab ov e"]'::jsonb, 3, 'Section 102(1) of the Companies Act, 2013'),
(63, 'Which one of the following required ordinary resolution?', '["To change the name of the company","To alter the article of association","To reduce share capital","to declare dividend"]'::jsonb, 3, 'Section 102(2) of the Companies Act, 2013'),
(64, 'Which one of the followin g required ordinary resolution?', '["the consideration of financial statement and the reports of the Board of directors and auditors","To increase share capital","To alter the Memorandum of association","To alter the article of association"]'::jsonb, 3, 'Section 102(2) of the Companies Act, 2013'),
(65, 'Which one of the followin g required ordinary resolution?', '["To change the registered office of the company","the appointment of director in place of those retiring and the appointment of , and the fixing of the remuneration of, the auditors","To reduce share capital","To alter the Memorandu m of association"]'::jsonb, 0, 'Section 102(2) of the Companies Act, 2013'),
(66, 'Penalty for contravention of Section 102(5) of the Companies Act, 2013. ( Explanatory statement)', '["Higher of - Fine up to Rs. 50,000 or - 5 * amount of benefit to person liable","Lower of - Fine up to Rs. 50,000 or - 5 * amount of benefit to person liable","Higher of - Fine up to Rs. 1,00,000 or - 5 * amount of benefit to person liable","Lower of - Fine up to Rs. 1,00,000 or - 5 * amount of benefit to person liable"]'::jsonb, 1, 'Section 102(2) of the Companies Act, 2013'),
(67, 'Quorum requirement for general meeting in case of a Public Company………', '["– 5 members personally present if members>1000 - 15 members personally","– 2 members personally present if members>1000 - 10 members personally","– 5 members personally present if members>1000 - 20 members personally","– 2 members personally present if members>1000 - 15 members present if 1000 < members<5000 - 30 members personally present if members>5000 present if 1000 < members<5000 - 30 members personally present if members>5000 present if 1000 < members<5000 - 50 members personally present if members>5000 personally present if 1000 < members<5000 - 50 members personally present if members>5000"]'::jsonb, 0, 'Section 102(5) of the Companies Act, 2013'),
(68, 'Quorum requirement for general meeting in case of a Private Company………', '["2 members personally present","As per AOA","2 members personally present or the numbers prescribed by article whichever is higher","None of the above"]'::jsonb, 0, 'Section 103(1) of the Companies Act, 2013'),
(69, 'If the quorum is not presented within ……… from the time appointed for holding a meeting of the company, the meeting shall stand adjourned.', '["15 minutes","Half an hour","One hour","Two hour"]'::jsonb, 2, 'Section 103(1) of'),
(70, 'If the quorum is not presented within half an hour from the time appointed for holding a meeting of the company, the meeting shall stand adjourned to …….', '["to the same day in the next week at the same time and place","to such other date and such other time and place as the Board may determine or as per AOA","the meeting if called by requisitionists shall stand cancelled","All of the above"]'::jsonb, 1, 'Section'),
(71, 'If the quorum is not present within half an hour from the time appointed for holding adjourned meeting then', '["Meeting shall stand terminated","Present member will be considered as quorum","Meeting will adjourned again","None of the above"]'::jsonb, 3, 'Section 103(2'),
(72, 'A general meeting of a Public Company was adjourned by the chairman for want of quorum. The meeting shall stand adjourned to the same day in next week, at the same time and place. In adjourned meeting also, quorum is not present within half an hour from the time appointed for holding meeting, then…….', '["Meeting shall stand terminated","Present member will be considered as quorum","Meeting will adjourned again","None of the above"]'::jsonb, 1, 'Section'),
(73, 'A person representing three member companies can be counted for the purpose of quorum in a general meeting of a Public Company.', '["Yes, A person representing three member companies will be counted as 1 for only one member in the computation of the quorum","Yes, A person representing three member companies will be counted as 2 for two member in the computation of the quorum","Yes, A person representing three member companies will be counted as 3 in the computation of the quorum","No, A person representing three member companies will not be counted."]'::jsonb, 1, 'Section 103(3) of the Companies Act, 2013'),
(74, 'Both the joint owners of shares present at the meeting can be counted as two shareholders for the purpose of quorum in a general meeting of a Public Company. True or False.', '["True","False","Partly True, counted as two but not for quorum","no provision regarding it"]'::jsonb, 2, 'Section 103 of the Companies Act, 2013'),
(75, 'A single member present at the meeting can be counted for the purpose of quorum in a general meeting of a Public Company.', '["Yes","No","Required joint shareholders only","Counted In specific meetings only"]'::jsonb, 1, 'For the purpose of quorum in a general meeting of a Public Company, joint shareholders will be collectively regarded as one shareholder. ( Section 103 of the Companies Act, 2013)'),
(78, 'The Annual General Meeting of XYZ Ltd. was held on 30 th April, 2015. The Article of Association of the company is silent regarding the quorum of the General meeting. Only 25 members were personally present in the above meeting out of 7000 members within half an hour. Whether Chairman can adjourn the meeting.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 103 of the Companies Act, 2013, quorum is required in case of Public Company – – 5 members personally present if members>1000 - 15 members personally present if 1000 < members<5000 - 30 members personally present if members>5000'),
(79, 'The Annual General Meeting of XYZ Pvt. Ltd. was held on 30 th April, 2015. The Article of Association of the company is silent regarding the quorum of the General meeting. Only 2 members were personally present in the above meeting out of 180 members within half an hour. Whether Chairman can adjourn the meeting.', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'As per Section 103 of the Companies Act, 2013, quorum is required in case of Public Company – – 5 members personally present if members>1000 - 15 members personally present if 1000 < members<5000 - 30 members personally present if members>5000'),
(80, 'State the rights of Proxy.', '["Right to attend the meeting and right to vote on poll","Right to act on behalf of the appointing member","Right to demand a poll if eligible u/s 109 of the Companies Act, 2013","All of the above"]'::jsonb, 0, 'As per Section 103 of the Companies Act, 2013, Quorum requirement for general meeting in case of a Private Company is 2.'),
(81, 'State the restrictions on Proxies.', '["Not have right to speak in the meeting","cannot vote on show of hands","not counted for the purpose of quorum","All of the above"]'::jsonb, 3, 'Section 105(1) of the Companies Act, 2013'),
(82, 'The Proxy Form shall be in writing and signed by the member/Attorney. True or False.', '["True","False","Partly True","Partly False"]'::jsonb, 3, 'Section 105(1) of the Companies Act, 2013'),
(83, 'Every member entitled to vote at a meeting or on any resolution to be moved thereat shall be entitled to inspect proxies lodged during the period beginning …….. Hours before the time fixed for commencement of meeting and ending with the conclusion of the meeting at any time during the business hours of the Company.', '["12 Hours","24 Hours","48 Hours","60 Hours"]'::jsonb, 0, 'Section 105(6) of the Companies Act, 2013'),
(84, 'Every member entitled to vote at a meeting or on any resolution to be moved thereat shall be entitled to inspect proxies lodged during the period beginning 24 Hours before the time fixed for commencement of meeting and ending with the conclusion of the meeting at any time during the business hours of the Company. Provided ……. Days’ notice in writing of intension to inspect is given to the company.', '["1 day","2 days","3 days","7 days"]'::jsonb, 1, 'Section 105(8) of the Companies Act, 2013'),
(85, 'Mr. Ram, a shareholder of the company, after appointing Mr. Shyam as his proxy at meeting of the company, himself attended the meeting and voted on a particular resolution. Shyam thereafter claimed to exercise his vote. Whether he can do so?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 2, 'Section 105(8) of the Compa nies Act, 2013'),
(88, 'K, a shareholder of XYZ ltd. appoints L as his proxy to attend the general meeting of the company. Later K also attends the meeting. Both K and L voted on a particular resolution in the meeting. K’s vote was declared invalid by the chairman stating that since he has appointed the proxy and L’s vote has been considered as valid. Whether K can raise objection to the decision of the Chairman?', '["Yes","No","raise objection but with the approval of other members","raise objection but with the approval of BOD"]'::jsonb, 1, 'Section 105(8) of the Companies Act, 2013, Every member entitled to vote at a meeting or on any resolution to be moved thereat shall be entitled to inspect proxies lodged during the period beginning 24 Hours before the time fixed for commencement of meeting and ending with the conclusion of the meeting at any time during the business hours of the Company. Provided 3 Days’ notice in writing of intension to inspect is given to the company.'),
(89, 'A proxy has no right to speak at the general meeting of a company. True or False.', '["True","False","Partly True","Partly False, with permission of Chairman"]'::jsonb, 0, 'Where a shareholder who having appointed a proxy, personally attends and votes at the meeting, the proxy is revoked thereby. (Section 105 of the Companies Act, 2013)'),
(90, 'A proxy cannot vote on show of hands at the general meeting of a company. True or False.', '["True","False","Partly True","Partly False, with permission of Chairman"]'::jsonb, 0, 'Section 105(1) of the Companies Act, 2013, it is one of the restriction of Proxies.'),
(91, 'A proxy is not counted for the purpose of quorum of the general meeting of a company. True or False.', '["True","False","Partly True","Partly False, with permission of Chairman"]'::jsonb, 0, 'Section 105(1) of the Companies Act, 2013, it is one of the restriction of Proxies.'),
(92, 'Proxy have right to vote on poll in general meeting of the company. True or False.', '["True","False","Partly True, with permission of Chairman","Partly False, have right to vote but not in GM"]'::jsonb, 0, 'Section 105(1) of the Companies Act, 2013, it is one of the restriction of Proxies'),
(93, 'Proxy have right to demand a poll (if eligible u/s 109) in general meeting of the company. True or False.', '["True","False","Partly True, with permission of Chairman","Partly False, have right to demand but not in GM"]'::jsonb, 0, 'Section 105(1) of the Companies Act,'),
(94, 'The proxy shall file with the company in Form No……', '["MGT 8","MGT 9","MGT 10","MGT 11"]'::jsonb, 0, 'Section 105(1) of the'),
(95, 'The chairman of the meeting of a company received a Proxy 48 hours before the time fixed for the start of the meeting. He refused to accept the proxy on the ground that the Article of the company provided that a Proxy must be filed 60 hours before the start of the meeting. Whether Proxy holder can compel the chairman to admit the proxy?', '["Yes","No","Partly Yes(with the permission of BOD and shareholders)","Partly No"]'::jsonb, 3, 'Section'),
(96, 'The AOA of a Public company requires the instrument appointing a proxy to be received by the company 75 hours before the meeting. Is it valid requirement?', '["Yes","No","Partly Yes(with the permission of BOD and shareholders)","Partly No"]'::jsonb, 0, 'Section 105(7) of the Companies Act, 2013, if AOA of a'),
(97, 'State the grounds to bar a member from voting.', '["Any call or other sums presently payable by him have not been paid","The company has exercised any right of lien","Both a and b","either a or b"]'::jsonb, 1, 'Section 105(7) of the Companies Act, 2013, if AOA of a company requires for a longer period than 48 hours before meeting, such requirement by AOA shall be treated as 48 hours to deposit proxy form.'),
(100, 'Any company may use postal ballot for transacting any items of business other than', '["Ordinary Business","Any business in respect of which directors have a right to be heard","Any business in respect of which auditors have a right to be heard","All of the above"]'::jsonb, 1, 'Section 106 and 114(2) of the Companies Act, 2013, a resolution shall be a special resolution when the votes cast in favour of the resolution by members are not less than 3 times the number of votes, if any, cast against the resolution.'),
(101, 'State the types of Voting.', '["Voting by show of hands (Section 107 of the Companies Act, 2013)","Voting through Electronic Means (Section 108 of the Companies Act, 2013) and Postal ballot(Section 110 of the Companies Act, 2013)","Voting by Poll(Section 109 of the Companies Act, 2013)","All of the above"]'::jsonb, 3, 'Section 110(1) of the Companies Act, 2013, above items of business can be transacted only at a meeting.'),
(102, 'Entries have to be made in the Register within …….days of the date of approval by the Board or Committee thereof by approving the allotment or transfer as the case may be.', '["7","15","30","60"]'::jsonb, 3, NULL),
(103, 'Joint holders of shares may request the company to', '["enter their names on the register in a certain order","execute transfers to have their holding split","Only one of their names should appear in the records of the company.","Both a and b"]'::jsonb, 0, 'Rule 5 of the Companies (Management & Administration) Rules, 2014.'),
(104, 'Maintenance of index of names in the registers is not necessary where the number of members is less than……….', '["20","50","100","500"]'::jsonb, 3, 'The articles of most companies provide that, in the case of exclusion of the other joint holders, and for this purpose, seniority shall be determined by the order in which the names stand in the register of members.'),
(105, 'Where any declaration is received by the company regarding beneficial interest, the company shall make note of such declaration in the register of members and shall file, within a period of ………..days from the date of receipt of declaration by it,', '["30","60","90","None of the above"]'::jsonb, 1, 'Rule 6 of the Companies (Management & Administration) Rules, 2014 states that the maintenance of index is not necessary where the number of members is less than 50.'),
(106, 'The register of members along with the index shall be preserved for', '["7 years","8 years","10 years","Permanently"]'::jsonb, 0, 'Where any declaration is received by the company under section 89, the company shall make note of such declaration in the register of members and shall file, within a period of 30 days from the date of receipt of declaration by it, a return in Form MGT - 6 with the ROC in respect of such declaration with the required fee.'),
(107, 'The company shall, within ………….days from the date of the opening of any foreign register, file with the Registrar of Companies notice of the situation of the office.', '["7","30","60","90"]'::jsonb, 3, 'Section 94 of the Companies Act, 2013.'),
(108, 'A company opens the registers and indices from 1-2 p.m. every working day. Is it in contravention of Section 94?', '["Yes","No","Partly Yes","Partly No"]'::jsonb, 1, 'Section 88 of the Companies Act, 2013. – Foreign registers compliance.'),
(109, 'A holder of shares in a company who does not hold the beneficial interest such share, shall file with the company, a declaration to that effect in Form MGT —4, in duplicate, within …………….days from the date on which his name is entered in the register of', '["30","60","90","none of the above"]'::jsonb, 0, NULL),
(110, 'A beneficial owner, shall file with the company, a declaration disclosing such Interest In Form MGT-5 in duplicate, within ……..days after acquiring such beneficial Interest in the shares of the company.', '["30","60","90","none of the above"]'::jsonb, 0, 'A person whose name is entered in the register of members of a company as the holder of shares in that company but who does not hold the beneficial interest such share, shall file with the company, a declaration to that effect in Form MGT - 4, in duplicate, within 30 days from the date on which his name is entered in the register of members of such company.'),
(111, 'The company shall transmit to its registered office in India, a copy of every entry in any foreign register within ……………days after the entry is made.', '["7","15","30","90"]'::jsonb, 0, 'Every person holding and exempted from furnishing declaration or acquiring a beneficial interest in shares of a company not registered in his name, shall file with the company, a declaration disclosing such interest in Form MGT 5 in duplication disclosing such interest in Form MGT 5 in duplicate, within 30 days after acquiring such beneficial interest in the shares of the company.'),
(112, 'The company which fails to comply with the provisions of section 89, makes punishable the company and every defaulting officer with a fine which shall not be less than Rs………. but which may go up to Rs. ……………with further fine of Rs. ……….per day during.', '["500, 1000,1000","1000, 3000, 1000","500, 3000, 1000","1000, 5000, 1000"]'::jsonb, 1, 'Section 88- Foreign Registers Compliances'),
(113, 'Copies of annual return along with the copy of certificates and the documents required to be annexed thereto shall be preserved for a period of years from the date of filing of the annual return.', '["7","8","10","20"]'::jsonb, 0, 'Section 89(7) refers to the company which falls to comply with the provisions of section 89, makes punishable the company and every defaulting officer with a fine which shall not be less than Rs. 500 but which may go up to Rs. 1,000 with'),
(114, 'The company and every officer of the company who fails to maintain registers as prescribed In the act shall be punishable with fine which shall not be less than Rs. …….but which may extend to Rs. ………. And where the failure is a continuing one.', '["100000, 500000","50000, 300000","50000, 500000","100000, 300000"]'::jsonb, 1, NULL),
(115, 'If the beneficial owner or the holder of such shares fails to make a declaration on that behalf, they shall be fined with amount up to Rs……… and additionally Rs………… per day during which the failure continues. A., B.,', '["100000, 1000","50000, 3000","100000, 3000","50000, 1000"]'::jsonb, 1, 'Section 88 deals with the penalty for contravention of the provisions of section 88, i.e. failure to maintain registers in accordance with the provisions of Section 88(1) and 88(2) of the Act. It states that the company and every officer of the company who Is in default shall be punishable with fine which shall not be less'),
(116, 'Registers can be kept at any place in India In which more than ……of total members reside provided a special resolution has been passed at a general meeting.', '["1%","5%","10%","20%"]'::jsonb, 3, 'Section 89(5) applies to those who are required to make a declaration. But fail to do so. The penalty for their failure, without any reasonable explanation, is fine'),
(117, 'The annual return, filed by a listed company or a company having paid-up share capital of Rs…….or more; or a turnover of Rs…….. Crore or more, shall be certified by a Company Secretary in practice.', '["10, 50","20,100","50, 200","100, 500"]'::jsonb, 2, 'the registers shall be maintained at the registered office of the company unless a special resolution Is passed in a general meeting authorizing the keeping of the register at any other place within the city, town or village in which the registered office is situated or any other place in India in which more than 1/10th of the total members entered in the register of members reside.'),
(118, 'The extracts or copies of registers and indices can be taken by', '["any member","debenture holder","beneficial owner","All of the above"]'::jsonb, 0, 'The annual return, filed by a listed company or a company having paid- up share capital of Rs.10 crore or more; or a turnover of Rs.50 crore or more, shall be certified by a Company Secretary in practice'),
(119, 'The annual return has to be signed by…..', '["CA, CS","CA, a director","CS, a Director","CA, CS and a director"]'::jsonb, 3, 'Any member, debenture holder or security holder or beneficial owner can take the extracts during any business without payment of any fee or can also get copies thereof with payment of fee not exceeding Rs.10 for each page. Such copies or entries or return shall be supplied within 7 days of deposit of fee.'),
(120, 'The company has to maintain registers of', '["members","debenture-holders","any other security holders","all of the above"]'::jsonb, 2, 'The annual return has to be signed by a director company and the company secretary; and in no company secretary, by a company secretary and in case, there is no company secretary, by a company secretary in practice.'),
(121, 'The annual return shall be file with the ROC within ……… days from which the Annual General Meeting (‘AGM'') is held or should have been held in any year,', '["15","30","60","90"]'::jsonb, 3, 'Section 88(1) of the Companies Act, 2013 seeks to provide that every company shall keep and maintain the register of members, register of debenture-holders and register of any other security holders.'),
(122, 'A company secretary in practice who signs the annual return can certify the same.', '["True","False","Partly True","Partly False"]'::jsonb, 2, 'The annual return shall be file with the ROC within 60 days from which the Annual General Meeting (''AGM) is held or should have been held in any year'),
(123, 'A company may close the register of members, debenture-holders and other security holders by giving minimum …………..notice or such lesser period as specified by SEBI.', '["21 clear days","30 days","7 days","15 days"]'::jsonb, 1, NULL),
(124, 'Inspection of registers and indices shall cost a maximum of Rs……. or any lesser amount mentioned in the articles, for each inspection.', '["10","20","50","100"]'::jsonb, 2, 'A company may close the register of members, debenture- holders and other security holders by giving minimum 7 days'' notice or such lesser period as specified by Securities Exchange Board of India.'),
(125, 'In case of a company not limited by shares, the register shall not contain', '["Permanent Account Number or Corporate Identity Number","Nationality","Marital status","Date of becoming the member"]'::jsonb, 2, 'The registers and indices shall be open for inspection during business hours, at such reasonable time on event working day as the board may decide upon payment of fees as may be specified In the articles of association of the company, but which may not exceed RS. 50 for each Inspection. Also, a reasonable time shall be not less than 2 hours on every working day for which the inspection shall be open by the company.'),
(126, 'If a company secretary in practice, certifies the annual return otherwise than in accordance with this section and the rules made thereunder, he shall be punishable with fine which shall not be less than Rs.50, 000 but which may extend to RS. 5, 00,000 or ………….', '["3 Months","6 Months","1 Year","2 Years"]'::jsonb, 2, 'In case of a company not limited by shares, the register shall contain the following particulars, in respect of each member- Name of the member, address (registered of address in case the member is a body corporate); email address; Permanent Account Number or Corporate Identity Number (''CIN); Nationality; in case member is a minor - name of his guardian and the date of birth of the member, name and address of the nominee; Date of becoming the member; Date of cessation; Amount of guarantee, if any; Any other interest, if any; and Instructions, if any, given by the member with regard to sending of notices, etc.'),
(127, 'The registers may be closed for any period not exceeding ……….days at any one time and for an aggregate period of ………….days in one year.', '["30, 60","30, 45","45, 90","60, 90"]'::jsonb, 1, NULL),
(128, 'Every listed company is mandated to file with the ROC a return with respect to any changes In the number of shares held by ………….within 15 days of such change.', '["Directors and Promoters","Promoters and Top 10 shareholders","Directors and Top 10 shareholders","Directors, Promoters and Top 10 shareholders"]'::jsonb, 1, 'The registers may be closed for any period not exceeding 30 days at any one time and for an aggregate period of 45 days in one year.'),
(129, 'If the company defaults in filing the annual return, the company shall be punishable with fine which shall not be less than Rs……………. but which may extend to Rs…………….', '["50000, 500000","100000, 500000","50000, 200000","100000, 200000"]'::jsonb, 1, NULL),
(130, 'Every listed company shall file in Form MGT -10 a return with respect to changes relating to either increase or decrease of ………. percent or more in the shareholding position of promoters and top 10 shareholders of the company in each case.', '["1","2","5","10"]'::jsonb, 0, NULL),
(131, 'Section 90 simply enables the ………..to appoint one or more competent persons to investigate and report as to the beneficial ownership with regard to any share or class of shares.', '["Registrar","NCLT","Central Government","Company Law Board"]'::jsonb, 1, NULL),
(132, 'The……….has a casting vote in Board Meetings and general meetings, if specifically empowered by the articles of the Company.', '["Managing Director","Chartered Accountant","Company Secretary","Chairman"]'::jsonb, 2, NULL),
(136, 'The authorized representative of a corporate member can exercise the following rights :', '["right to speak","right to vote on poll","right to vote by show of hands","all of the above"]'::jsonb, 1, NULL),
(137, 'Special notice shall be sent by members to the company not earlier than….. Months but at least ……days before the date of meeting.', '["1, 21 clear","3,21 clear","1, 14","3, 14"]'::jsonb, 3, 'A person authorized by resolution as above, shall be entitled to exercise the same rights and powers, including the right to vote by proxy and by postal ballot, on behalf of the body corporate which he represents as that body could exercise If It were an individual member, creditor or holder of debentures of the company.'),
(138, 'In a company with 1000 members the quorum is:', '["2","5","15","30"]'::jsonb, 3, NULL),
(139, 'For a private company quorum is………. Members personally present:', '["1","2","5","10"]'::jsonb, 3, NULL),
(140, 'Inspection of proxies can be done during the meeting and ………. Hours before the meeting before its commencement, and the inspection is to be given only during business hours.', '["12","24","48","72"]'::jsonb, 1, 'Section 103 of the Companies Act, 2013'),
(141, 'In order to properly call a general meeting the notice should be sent at least ……….days before the meeting, to all the members, legal representative of any deceased member or the assignee of insolvent members, the auditors and directors, in writing or electronic form.', '["21 days","21 clear days","21 full days","21 Complete days"]'::jsonb, 1, NULL),
(142, 'Any accidental omission to give notice to, or non-receipt of such notice to any member or other person who is entitled to such notice for any meeting shall invalidate the proceedings of the meeting.', '["True","False","Partly True","Partly False"]'::jsonb, 1, 'Section 101 of the Companies Act, 2013'),
(143, 'In case the meeting was called by the requisitionist under section 100 of the Act, then the same shall stand if the quorum is not present', '["adjourned","cancelled","members present will be quorum","No. of requisitionists will be quorum"]'::jsonb, 1, 'The omission must be designed or deliberate to invalidate the proceedings.'),
(144, 'The register of debenture-holder or any other security holder along with the index shall be preserved for a period of ……………….years from the date preservative of register of debenture holding other security holder of redemption of debentures or securities.', '["7","8","10","20"]'::jsonb, 1, NULL),
(145, 'Notice of the general meeting shall be sent to……', '["Assignee of the insolvent member","Managers of the corporate owners","Family member of deceased member","None of the above"]'::jsonb, 1, NULL),
(146, 'Section 104 of the Companies Act, 2013 seeks to provide that unless the articles of association of the Company otherwise provide, the members, personally present, shall elect among themselves to be the Chairman by:', '["Show of Hands","Poll","Postal Ballot","E-Voting"]'::jsonb, 0, NULL),
(149, 'If any inspection or the making of any extract or copy required under this section is refused, the company and every officer of the company who is in default, shall be liable for each such default, to a penalty of RS…….. for every day subject to a maximum', '["1000, 100000","1000, 500000","2000, 200000","2000, 500000"]'::jsonb, 1, NULL),
(150, 'A proxy received ………..hours before the meeting will be valid even if the articles provide for a longer period.', '["12","24","48","72"]'::jsonb, 0, NULL),
(151, 'In case of the adjourned meeting or change of day, time or place of meeting Under section 103(2), the company shall give not less than……….. days'' notice to the members either individually or by publishing an advertisement in the newspaper.', '["2","3","4","5"]'::jsonb, 2, NULL),
(152, 'A person appointed as proxy shall act on behalf of such member or number of members not exceeding……………. and holding in aggregate not more than ......... per cent of the total share capital of the company carrying voting rights.', '["10, 5","10, 10","50, 10","20, 5"]'::jsonb, 1, NULL),
(154, 'A proxy shall have the following rights -', '["right to speak","right to vote on poll","right to vote by show of hands","all of the above"]'::jsonb, 2, 'The Ordinary Businesses as prescribed in the Section 102(2) of the Companies Act, 1956 are as follows: -the consideration of financial statements and the reports of the Board of Directors and auditors; -the declaration of any dividend; -the appointment of directors in place of those retiring; -the appointment of and the fixing of the remuneration of, the auditors; Any businesses except the above 4(four) businesses shall be deemed to be ''Special Businesses''.'),
(155, 'Who shall vote in case of joint holders if they are in disagreement?', '["any of the joint holders","determined on the basis of the order in which their names appear in the register","all of them","any of them"]'::jsonb, 1, 'A proxy shall not have the right to speak at such meeting and shall not be entitled to vote except on a poll.'),
(156, 'In a company with 5000 members the quorum is :', '["2","5","15","30"]'::jsonb, 1, 'The voting in case of joint shareholders Is done in the order of seniority, which is determined on the basis of the order In which their names appear In the register of members/ shareholders. The joint- holders have a right to Instruct the company as to the order In which their names are to appear in the register.'),
(157, 'Special notice is required:', '["To appoint as auditor a person other than a retiring auditor","To remove a director under section 169(2) or to appoint a person to fill the vacancy caused by the dismissal of a director","To stand for directorship by a person other than retiring director","all of the above"]'::jsonb, 2, NULL),
(158, 'A general meeting can be called on a shorter notice if …………per cent of the members entitled to vote in that meeting give their consent in writing or by electronic mode.', '["85","90","95","100"]'::jsonb, 3, NULL),
(161, 'The gap between two AGMs shall not be more than………. months', '["12","15","18","21"]'::jsonb, 1, 'Section 109 of the Companies Act, 2013'),
(162, 'If a person is found guilty of tampering with the minutes of the proceedings of the meeting, he shall be punishable with imprisonment for a term which may extend to ………. years and with fine which shall not be less than Rs…………… but which may extend to Rs…………..', '["1, 100000, 500000","2, 25000. 100000","1. 50000,500000","2, 50000, 500000"]'::jsonb, 1, 'Section 96 of the Companies Act, 2013'),
(163, 'Any of the following matter shall not be included in the minutes of the meeting, which in the opinion of the Chairman of the meeting:', '["Is or could reasonably be regarded as defamatory of any person","Is Irrelevant or immaterial to the proceedings;","Is detrimental to the interests of the company.","All of the above"]'::jsonb, 1, NULL),
(164, 'A general meeting can be called by', '["Board of directors","Requisitionists","NCLT","All of the above"]'::jsonb, 3, NULL),
(165, 'The company and every officer of the company who is in default or in contravention of section 96-98, shall be punishable with fine which may extend to Rs…………. and in the case of a continuing default, with a further fine which may extend to Rs …………….', '["100000, 5000","500000,1000","100000, 1000","500000, 5000"]'::jsonb, 3, 'Directors- u/s 96 of the Companies Act, 2013 NCLT- u/s 97&98 of the Companies Act, 2013 Requisitionists- u/s 100 of the Companies Act, 2013'),
(166, 'The minutes book of the general meeting shall be preserved for:', '["7 years","8 years","10 years","Permanently"]'::jsonb, 0, 'Section 99 of the Compani es Act, 2013'),
(167, 'Inspection of minute’s book can be carried out by……', '["a member","a director","a debenture holder","all of the above"]'::jsonb, 3, NULL),
(168, 'If the Board does not call a meeting within ……… days from the date of receipt of requisition, then the requisitionists may themselves call a meeting within a period of ……..months from the date of requisition.', '["21, 3","21, 1","7, 1","7, 3"]'::jsonb, 0, 'Section 199 of the Companies Act, 2013'),
(169, 'The minutes shall be prepared and kept within ……..days of the conclusion of every such meeting concerned or passing of resolution by postal ballot in books.', '["15","30","60","90"]'::jsonb, 0, 'Section 100 of the Companies Act, 2013'),
(170, 'The First AGM shall be held within……..months from the end of financial year.', '["6","9","12","15"]'::jsonb, 1, 'Section 118 of the Companies Act, 2013'),
(171, 'Except for first AGM, AGM shall be held within…….months from the end of financial year.', '["3","6","9","12"]'::jsonb, 1, NULL),
(172, 'Registrar may grant an extension of ………..months for holding the AGM.', '["1","3","6","9"]'::jsonb, 1, NULL)
) as v(question_no, question, options, correct_index, hint)
where b.title = 'CA Inter Law MCQs by Darshan Khare'
on conflict (book_id, chapter_no, question_no) do nothing;
`;
